    faq: [
      { q: { en: 'Can you build the product too, not just the website?', hu: 'A terméket is meg tudod építeni, nem csak a weboldalt?', sk: 'Viete postaviť aj produkt, nielen web?' }, a: { en: 'Yes — web applications with React front ends, Java/Spring back ends and AI integration (LLMs, RAG, function calling) are a core service.', hu: 'Igen — a React frontendes, Java/Spring backendes, MI-integrációs (LLM, RAG, function calling) webalkalmazások a fő szolgáltatások közé tartoznak.', sk: 'Áno — webové aplikácie s frontendom v Reacte, backendom v Java/Spring a AI integráciou (LLM, RAG, function calling) sú jednou z hlavných služieb.' } },
      { q: { en: 'Why a coded demo instead of a video?', hu: 'Miért kódolt demó videó helyett?', sk: 'Prečo demo v kóde namiesto videa?' }, a: { en: 'It loads faster, stays sharp on every screen, can be interactive and is easy to update when the product changes.', hu: 'Gyorsabban tölt, minden képernyőn éles marad, lehet interaktív, és könnyű frissíteni, ha a termék változik.', sk: 'Načíta sa rýchlejšie, zostane ostré na každej obrazovke, môže byť interaktívne a ľahko sa aktualizuje, keď sa produkt zmení.' } },
      { q: { en: 'Can the team edit the site without a developer?', hu: 'Szerkesztheti a csapat fejlesztő nélkül?', sk: 'Môže tím upravovať web bez vývojára?' }, a: { en: 'Yes — blog, docs, changelog and pricing can be edited in a CMS or as Markdown in your repository.', hu: 'Igen — a blog, a dokumentáció, a changelog és az árazás CMS-ben vagy Markdownként a repóban szerkeszthető.', sk: 'Áno — blog, dokumentáciu, changelog aj cenník možno upravovať v CMS alebo ako Markdown vo vašom repozitári.' } },
      { q: { en: 'Do you work with early-stage startups?', hu: 'Korai fázisú startupokkal is dolgozol?', sk: 'Spolupracujete aj so startupmi v počiatočnej fáze?' }, a: { en: 'Yes — a focused landing page and a small MVP are a good way to test an idea before a larger build.', hu: 'Igen — egy fókuszált landing oldal és egy kis MVP jó módja egy ötlet tesztelésének a nagyobb fejlesztés előtt.', sk: 'Áno — cielená landing page a malé MVP sú dobrý spôsob, ako otestovať nápad pred väčším vývojom.' } },
      { q: { en: 'How long does it take?', hu: 'Mennyi idő alatt készül el?', sk: 'Ako dlho to trvá?' }, a: { en: 'A landing page takes about 2–3 weeks, a product website 4–8 weeks, an MVP typically 2–4 months.', hu: 'Egy landing oldal kb. 2–3 hét, egy termékweboldal 4–8 hét, egy MVP jellemzően 2–4 hónap.', sk: 'Landing page trvá približne 2–3 týždne, produktový web 4–8 týždňov, MVP zvyčajne 2–4 mesiace.' } },
    ],
