    faq: [
      { q: { en: 'Do you have experience with financial systems?', hu: 'Van tapasztalatod pénzügyi rendszerekkel?', sk: 'Máte skúsenosti s finančnými systémami?' }, a: { en: 'Yes — banking platform modernisation, a stock market web app and an accounting system are among the case studies on this site.', hu: 'Igen — banki platformok modernizációja, tőzsdei webalkalmazás és könyvelési rendszer is szerepel az oldal esettanulmányai között.', sk: 'Áno — modernizácia bankovej platformy, webová aplikácia pre burzu a účtovný systém patria medzi prípadové štúdie na tomto webe.' } },
      { q: { en: 'How is security handled?', hu: 'Hogyan kezeled a biztonságot?', sk: 'Ako je riešená bezpečnosť?' }, a: { en: 'HTTPS everywhere, strict security headers, minimal third-party scripts, input validation and least-privilege access; deeper audits and penetration tests can be arranged with specialists.', hu: 'Mindenhol HTTPS, szigorú biztonsági fejlécek, minimális külső szkript, bemeneti ellenőrzés és legkisebb jogosultság elve; mélyebb auditot és behatolásteszt szakértőkkel szervezhető.', sk: 'HTTPS všade, prísne bezpečnostné hlavičky, minimum skriptov tretích strán, validácia vstupov a prístup s najnižšími potrebnými oprávneniami; hlbšie audity a penetračné testy sa dajú zabezpečiť so špecialistami.' } },
      { q: { en: 'Can the site meet regulatory requirements?', hu: 'Meg tud felelni a szabályozói elvárásoknak?', sk: 'Môže web spĺňať regulačné požiadavky?' }, a: { en: 'The site is built to display the disclosures, risk warnings and privacy information your compliance team provides; the legal content itself stays with them.', hu: 'Az oldal úgy készül, hogy megjelenítse a megfelelőségi csapatod által adott közzétételeket, kockázati figyelmeztetéseket és adatvédelmi információkat; a jogi tartalom felelőssége náluk marad.', sk: 'Web je navrhnutý tak, aby zobrazoval povinné informácie, upozornenia na riziká a informácie o ochrane súkromia, ktoré dodá váš compliance tím; samotný právny obsah zostáva v jeho rukách.' } },
      { q: { en: 'Can it connect to our core systems?', hu: 'Összeköthető a központi rendszereinkkel?', sk: 'Dá sa web prepojiť s našimi kľúčovými systémami?' }, a: { en: 'Yes, through APIs or secure integration layers — integrations with banking systems are part of the experience.', hu: 'Igen, API-kon vagy biztonságos integrációs rétegen keresztül — a banki rendszerekkel való integráció is a tapasztalat része.', sk: 'Áno, cez API alebo bezpečné integračné vrstvy — integrácie s bankovými systémami sú súčasťou mojich skúseností.' } },
      { q: { en: 'How long does it take?', hu: 'Mennyi idő alatt készül el?', sk: 'Ako dlho to trvá?' }, a: { en: 'A marketing site takes about 4–8 weeks; calculators and onboarding 2–4 months; portals are planned in phases.', hu: 'Egy marketingoldal kb. 4–8 hét; kalkulátorok és regisztráció 2–4 hónap; a portálokat szakaszokra bontva tervezzük.', sk: 'Marketingový web trvá približne 4–8 týždňov; kalkulačky a onboarding 2–4 mesiace; portály sa plánujú po etapách.' } },
    ],
    interest: { en: 'Website for fintech / finance (Vaulmere style)', hu: 'Weboldal fintech / pénzügyi cégnek (Vaulmere stílus)', sk: 'Web pre fintech / financie (v štýle Vaulmere)' },
