    demoText: {
      en: 'Révhajlat Rezidencia is a fictional riverside development: an interactive elevation where each floor shows its apartments, an apartment finder and a slider that moves the sun across a floor plan from morning to evening.',
      hu: 'A Révhajlat Rezidencia egy kitalált dunaparti fejlesztés: interaktív homlokzat, ahol minden emelet mutatja a lakásait, lakáskereső és egy csúszka, ami reggeltől estig végigviszi a napot az alaprajzon.',
      sk: 'Révhajlat Rezidencia je vymyslený rezidenčný projekt pri rieke: interaktívna fasáda, kde každé podlažie ukazuje svoje byty, vyhľadávač bytov a posuvník, ktorý posúva slnko ponad pôdorys od rána do večera.',
    },
    prices: [
      { name: { en: 'Project website', hu: 'Projektoldal', sk: 'Web projektu' }, range: { en: '€1,600–4,000', hu: '600 ezer–1,5 M Ft', sk: '1 600–4 000 €' }, text: { en: 'Story, renders, location, apartment list and enquiry form.', hu: 'Történet, látványtervek, elhelyezkedés, lakáslista és érdeklődési űrlap.', sk: 'Príbeh, vizualizácie, lokalita, zoznam bytov a dopytový formulár.' } },
      { name: { en: 'With interactive availability', hu: 'Interaktív lakáskeresővel', sk: 'S interaktívnou dostupnosťou' }, range: { en: '€3,300–8,000', hu: '1,2–3 M Ft', sk: '3 300–8 000 €' }, text: { en: 'Interactive building, apartment finder, floor plans, admin for statuses.', hu: 'Interaktív épület, lakáskereső, alaprajzok, státuszkezelő admin.', sk: 'Interaktívna budova, vyhľadávač bytov, pôdorysy, administrácia stavov.' } },
      { name: { en: 'Sales integration', hu: 'Értékesítési integráció', sk: 'Integrácia predaja' }, range: { en: 'from €8,000', hu: '3 M Ft-tól', sk: 'od 8 000 €' }, text: { en: 'CRM/sales system sync, reservations and multi-project portal.', hu: 'CRM-/értékesítési rendszer szinkron, foglalás és több projektet kezelő portál.', sk: 'Synchronizácia s CRM/predajným systémom, rezervácie a portál pre viac projektov.' } },
    ],
    faq: [
      { q: { en: 'Who updates the apartment statuses?', hu: 'Ki frissíti a lakások státuszát?', sk: 'Kto aktualizuje stavy bytov?' }, a: { en: 'Your sales team in a simple admin — or automatically from the sales system or CRM if you use one.', hu: 'Az értékesítő csapat egy egyszerű adminban — vagy automatikusan az értékesítési rendszerből vagy a CRM-ből, ha használtok ilyet.', sk: 'Váš obchodný tím v jednoduchej administrácii — alebo automaticky z predajného systému či CRM, ak ho používate.' } },
      { q: { en: 'Do we need a 3D model of the building?', hu: 'Kell 3D modell az épületről?', sk: 'Potrebujeme 3D model budovy?' }, a: { en: 'No — the interactive elevation is built on your renders; a 3D model is an optional extra.', hu: 'Nem — az interaktív homlokzat a látványterveitekre épül; a 3D modell opcionális extra.', sk: 'Nie — interaktívna fasáda sa stavia na vašich vizualizáciách; 3D model je voliteľný doplnok.' } },
      { q: { en: 'Can one site handle several projects?', hu: 'Egy oldal több projektet is kezelhet?', sk: 'Zvládne jeden web viac projektov?' }, a: { en: 'Yes, as a developer portal with a page and finder per project.', hu: 'Igen, fejlesztői portálként, projektenként saját oldallal és keresővel.', sk: 'Áno, ako developerský portál so stránkou a vyhľadávačom pre každý projekt.' } },
      { q: { en: 'Can buyers reserve online?', hu: 'Foglalhatnak a vevők online?', sk: 'Môžu si kupujúci rezervovať online?' }, a: { en: 'Usually enquiries and viewing requests work best; online reservations with a deposit are possible when your sales process allows it.', hu: 'Általában az érdeklődés és a bejárási kérés működik a legjobban; előleges online foglalás is lehetséges, ha az értékesítési folyamat megengedi.', sk: 'Zvyčajne najlepšie fungujú dopyty a žiadosti o obhliadku; online rezervácie so zálohou sú možné, ak to váš predajný proces umožňuje.' } },
      { q: { en: 'How long does it take?', hu: 'Mennyi idő alatt készül el?', sk: 'Ako dlho to trvá?' }, a: { en: 'A project site takes about 3–5 weeks; with the interactive building and finder 6–10 weeks — ideally ready for the start of sales.', hu: 'Egy projektoldal kb. 3–5 hét; interaktív épülettel és lakáskeresővel 6–10 hét — ideális esetben az értékesítés indulására.', sk: 'Web projektu trvá približne 3–5 týždňov; s interaktívnou budovou a vyhľadávačom 6–10 týždňov — ideálne pripravený na začiatok predaja.' } },
    ],
    interest: { en: 'Website for a residential development (Révhajlat style)', hu: 'Weboldal lakóparknak (Révhajlat stílus)', sk: 'Web pre rezidenčný projekt (v štýle Révhajlat)' },
